"use client";

import { featuredProjects } from "../lib/projects";

const CATEGORY = {
  mobile:       { color: "#60a5fa", bg: "rgba(96,165,250,0.12)",  label: "Mobile"    },
  web:          { color: "#a1a1aa", bg: "rgba(161,161,170,0.12)", label: "Web"       },
  "ai-tool":    { color: "#f87171", bg: "rgba(248,113,113,0.12)", label: "AI Tool"   },
  "client-work":{ color: "#fb923c", bg: "rgba(251,146,60,0.12)",  label: "Client"    },
  community:    { color: "#facc15", bg: "rgba(250,204,21,0.12)",  label: "Community" },
  experiment:   { color: "#a78bfa", bg: "rgba(167,139,250,0.12)", label: "Experiment"},
} as const;

function getCat(category: string) {
  return CATEGORY[category as keyof typeof CATEGORY] ?? { color: "#a1a1aa", bg: "rgba(161,161,170,0.12)", label: category };
}

/* Unique gradient per project so the cover area has real visual identity */
const COVER_GRADIENTS: Record<string, string> = {
  filmsort:       "linear-gradient(135deg, #0f0c29 0%, #302b63 50%, #24243e 100%)",
  shazam:         "linear-gradient(135deg, #1a0005 0%, #3d0012 50%, #6b0021 100%)",
  cinevault:      "linear-gradient(135deg, #000428 0%, #004e92 100%)",
  buildoors:      "linear-gradient(135deg, #0a0a0a 0%, #1a2a1a 50%, #0d2b0d 100%)",
  "client-sites": "linear-gradient(135deg, #1a1400 0%, #3d3000 50%, #6b5500 100%)",
  "web3-community":"linear-gradient(135deg, #0d0019 0%, #1a003d 50%, #2d006b 100%)",
};

export default function Projects() {
  return (
    <section id="projects" style={{ background: "#000000", padding: "64px 0", borderTop: "1px solid rgba(255,255,255,0.05)" }}>
      <div style={{ maxWidth: 1100, margin: "0 auto", padding: "0 20px" }}>

        {/* Header */}
        <div style={{ marginBottom: 40 }}>
          <span className="section-label">Work</span>
          <h2 style={{ color: "#ffffff", marginBottom: 8 }}>Featured Projects</h2>
          <p style={{ color: "#71717a", fontSize: 15, maxWidth: 420 }}>
            Selected products built and shipped end-to-end.
          </p>
        </div>

        {/* Grid — 2 col on mobile, 3 on desktop */}
        <div className="projects-grid">
          {featuredProjects.map((p, i) => {
            const cat = getCat(p.category);
            const coverBg = COVER_GRADIENTS[p.id] ?? "linear-gradient(135deg, #111 0%, #1c1c1c 100%)";

            return (
              <article
                key={p.id}
                style={{
                  display: "flex",
                  flexDirection: "column",
                  borderRadius: 16,
                  overflow: "hidden",
                  background: "#0d0d0d",
                  border: "1px solid rgba(255,255,255,0.08)",
                  transition: "border-color 200ms ease, transform 200ms ease, box-shadow 200ms ease",
                  animationDelay: `${i * 60}ms`,
                }}
                onMouseEnter={e => {
                  const el = e.currentTarget as HTMLElement;
                  el.style.borderColor = `${cat.color}40`;
                  el.style.transform = "translateY(-3px)";
                  el.style.boxShadow = `0 20px 60px rgba(0,0,0,0.7), 0 0 40px ${cat.color}15`;
                }}
                onMouseLeave={e => {
                  const el = e.currentTarget as HTMLElement;
                  el.style.borderColor = "rgba(255,255,255,0.08)";
                  el.style.transform = "translateY(0)";
                  el.style.boxShadow = "none";
                }}
              >
                {/* ── Cover ───────────────────────────────────────────── */}
                <div style={{ position: "relative", width: "100%", paddingTop: "52%", background: coverBg, overflow: "hidden" }}>

                  {/* Subtle noise texture overlay */}
                  <div style={{
                    position: "absolute", inset: 0,
                    backgroundImage: "url(\"data:image/svg+xml,%3Csvg viewBox='0 0 256 256' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noise'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noise)' opacity='0.04'/%3E%3C/svg%3E\")",
                    opacity: 0.4,
                  }} />

                  {/* Large accent initial — decorative, not informational */}
                  <div style={{
                    position: "absolute", inset: 0,
                    display: "flex", alignItems: "center", justifyContent: "center",
                    pointerEvents: "none",
                  }}>
                    <span style={{
                      fontSize: "clamp(2.5rem, 8vw, 4rem)",
                      fontWeight: 900,
                      color: cat.color,
                      opacity: 0.12,
                      letterSpacing: -4,
                      userSelect: "none",
                      lineHeight: 1,
                    }}>
                      {p.title.slice(0, 3).toUpperCase()}
                    </span>
                  </div>

                  {/* Bottom gradient fade into card body */}
                  <div style={{
                    position: "absolute", bottom: 0, left: 0, right: 0, height: "60%",
                    background: "linear-gradient(to bottom, transparent, #0d0d0d)",
                  }} />

                  {/* Category chip — bottom-left, inside cover */}
                  <div style={{
                    position: "absolute", bottom: 10, left: 12,
                    display: "inline-flex", alignItems: "center", gap: 5,
                    padding: "3px 9px",
                    borderRadius: 6,
                    background: cat.bg,
                    border: `1px solid ${cat.color}30`,
                  }}>
                    <span style={{ width: 5, height: 5, borderRadius: "50%", background: cat.color, flexShrink: 0, display: "block" }} />
                    <span style={{ fontSize: 9, fontWeight: 800, color: cat.color, letterSpacing: 0.8, textTransform: "uppercase" }}>
                      {cat.label}
                    </span>
                  </div>

                  {/* Year — bottom-right */}
                  <div style={{ position: "absolute", bottom: 10, right: 12 }}>
                    <span style={{ fontSize: 10, fontWeight: 700, color: "rgba(255,255,255,0.3)", letterSpacing: 0.5 }}>{p.year}</span>
                  </div>
                </div>

                {/* ── Body ────────────────────────────────────────────── */}
                <div style={{ flex: 1, display: "flex", flexDirection: "column", padding: "14px 14px 12px", gap: 10 }}>

                  {/* Title + subtitle */}
                  <div>
                    <h3 style={{
                      fontSize: 13,
                      fontWeight: 800,
                      color: "#ffffff",
                      letterSpacing: -0.2,
                      lineHeight: 1.2,
                      marginBottom: 3,
                    }}>
                      {p.title}
                    </h3>
                    <p style={{ fontSize: 10, fontWeight: 500, color: "#52525b", letterSpacing: 0.1, lineHeight: 1.3 }}>
                      {p.subtitle}
                    </p>
                  </div>

                  {/* Description */}
                  <p style={{ fontSize: 11, lineHeight: 1.6, color: "#71717a", flex: 1 }}>
                    {p.summary}
                  </p>

                  {/* Tech pills */}
                  <div style={{ display: "flex", gap: 4, flexWrap: "wrap" }}>
                    {p.techStack.slice(0, 3).map(t => (
                      <span
                        key={t}
                        style={{
                          fontSize: 9,
                          fontWeight: 700,
                          letterSpacing: 0.3,
                          textTransform: "uppercase",
                          color: "#71717a",
                          background: "rgba(255,255,255,0.05)",
                          border: "1px solid rgba(255,255,255,0.07)",
                          borderRadius: 5,
                          padding: "2px 7px",
                        }}
                      >
                        {t}
                      </span>
                    ))}
                  </div>

                  {/* Divider */}
                  <div style={{ height: 1, background: "rgba(255,255,255,0.06)" }} />

                  {/* Action row */}
                  <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between" }}>
                    <span style={{
                      fontSize: 9,
                      fontWeight: 700,
                      textTransform: "uppercase",
                      letterSpacing: 0.5,
                      color: "#3f3f46",
                    }}>
                      {p.role}
                    </span>

                    {p.liveUrl ? (
                      <a
                        href={p.liveUrl}
                        target="_blank"
                        rel="noreferrer"
                        style={{
                          display: "inline-flex",
                          alignItems: "center",
                          gap: 5,
                          padding: "5px 12px",
                          borderRadius: 7,
                          background: "#ffffff",
                          color: "#000000",
                          fontSize: 10,
                          fontWeight: 800,
                          textDecoration: "none",
                          letterSpacing: 0.2,
                          transition: "opacity 150ms",
                        }}
                        onMouseEnter={e => { (e.currentTarget as HTMLAnchorElement).style.opacity = "0.85"; }}
                        onMouseLeave={e => { (e.currentTarget as HTMLAnchorElement).style.opacity = "1"; }}
                      >
                        <svg width="9" height="9" viewBox="0 0 24 24" fill="currentColor"><path d="M5 3l14 9-14 9V3z"/></svg>
                        View
                      </a>
                    ) : (
                      <span style={{
                        fontSize: 9,
                        fontWeight: 600,
                        color: "#3f3f46",
                        padding: "5px 10px",
                        borderRadius: 7,
                        border: "1px solid rgba(255,255,255,0.06)",
                        letterSpacing: 0.3,
                      }}>
                        Soon
                      </span>
                    )}
                  </div>
                </div>
              </article>
            );
          })}
        </div>

        {/* Footer CTA */}
        <div style={{ marginTop: 48, display: "flex", justifyContent: "center" }}>
          <a
            href="https://github.com/react-timmy"
            target="_blank"
            rel="noreferrer"
            className="btn-glass"
          >
            <svg width="15" height="15" viewBox="0 0 24 24" fill="currentColor"><path d="M12 2C6.477 2 2 6.484 2 12.017c0 4.425 2.865 8.18 6.839 9.504.5.092.682-.217.682-.483 0-.237-.008-.868-.013-1.703-2.782.605-3.369-1.343-3.369-1.343-.454-1.158-1.11-1.466-1.11-1.466-.908-.62.069-.608.069-.608 1.003.07 1.531 1.032 1.531 1.032.892 1.53 2.341 1.088 2.91.832.092-.647.35-1.088.636-1.338-2.22-.253-4.555-1.113-4.555-4.951 0-1.093.39-1.988 1.029-2.688-.103-.253-.446-1.272.098-2.65 0 0 .84-.27 2.75 1.026A9.564 9.564 0 0112 6.844c.85.004 1.705.115 2.504.337 1.909-1.296 2.747-1.027 2.747-1.027.546 1.379.202 2.398.1 2.651.64.7 1.028 1.595 1.028 2.688 0 3.848-2.339 4.695-4.566 4.943.359.309.678.92.678 1.855 0 1.338-.012 2.419-.012 2.747 0 .268.18.58.688.482A10.019 10.019 0 0022 12.017C22 6.484 17.522 2 12 2z"/></svg>
            More on GitHub
            <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5"><path d="M7 17L17 7M7 7h10v10"/></svg>
          </a>
        </div>
      </div>
    </section>
  );
}
